from collections import defaultdict
import bisect

class MajorityChecker:
    def __init__(self, arr):
        self.pos = defaultdict(list)
        for i, v in enumerate(arr):
            self.pos[v].append(i)
        self.n = len(arr)
        self.tree = [None] * (4 * self.n)
        self._build(arr, 1, 0, self.n - 1)

    def _build(self, arr, node, lo, hi):
        if lo == hi:
            self.tree[node] = (arr[lo], 1)
            return
        mid = (lo + hi) // 2
        self._build(arr, 2*node, lo, mid)
        self._build(arr, 2*node+1, mid+1, hi)
        self.tree[node] = self._merge(self.tree[2*node], self.tree[2*node+1])

    @staticmethod
    def _merge(a, b):
        if a[0] == b[0]:
            return (a[0], a[1] + b[1])
        if a[1] >= b[1]:
            return (a[0], a[1] - b[1])
        return (b[0], b[1] - a[1])

    def _query(self, node, lo, hi, l, r):
        if r < lo or hi < l:
            return (0, 0)
        if l <= lo and hi <= r:
            return self.tree[node]
        mid = (lo + hi) // 2
        return self._merge(self._query(2*node, lo, mid, l, r),
                           self._query(2*node+1, mid+1, hi, l, r))

    def query(self, left, right, threshold):
        cand, _ = self._query(1, 0, self.n - 1, left, right)
        lst = self.pos.get(cand)
        if not lst:
            return -1
        cnt = bisect.bisect_right(lst, right) - bisect.bisect_left(lst, left)
        return cand if cnt >= threshold else -1

