#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;

class MajorityChecker {
    struct Node { int val = 0, cnt = 0; };
    int n;
    vector<Node> t;
    vector<vector<int>> pos;

    Node merge(const Node& a, const Node& b) {
        if (a.val == b.val) return {a.val, a.cnt + b.cnt};
        if (a.cnt >= b.cnt) return {a.val, a.cnt - b.cnt};
        return {b.val, b.cnt - a.cnt};
    }
    void build(vector<int>& a, int node, int lo, int hi) {
        if (lo == hi) { t[node] = {a[lo], 1}; return; }
        int mid = (lo + hi) / 2;
        build(a, 2*node, lo, mid);
        build(a, 2*node+1, mid+1, hi);
        t[node] = merge(t[2*node], t[2*node+1]);
    }
    Node qry(int node, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) return {0, 0};
        if (l <= lo && hi <= r) return t[node];
        int mid = (lo + hi) / 2;
        return merge(qry(2*node, lo, mid, l, r), qry(2*node+1, mid+1, hi, l, r));
    }
public:
    MajorityChecker(vector<int>& arr) : n(arr.size()), t(4*n), pos(20001) {
        for (int i = 0; i < n; i++) pos[arr[i]].push_back(i);
        build((vector<int>&)arr, 1, 0, n-1);
    }
    int query(int left, int right, int threshold) {
        Node res = qry(1, 0, n-1, left, right);
        auto& v = pos[res.val];
        int cnt = upper_bound(v.begin(), v.end(), right) - lower_bound(v.begin(), v.end(), left);
        return cnt >= threshold ? res.val : -1;
    }
};

