import java.util.*;
class MajorityChecker {
    private int[] val, cnt;
    private List<List<Integer>> pos = new ArrayList<>();
    private int n;

    public MajorityChecker(int[] arr) {
        n = arr.length;
        val = new int[4*n]; cnt = new int[4*n];
        for (int i = 0; i <= 20000; i++) pos.add(new ArrayList<>());
        for (int i = 0; i < n; i++) pos.get(arr[i]).add(i);
        build(arr, 1, 0, n-1);
    }
    private void merge(int node, int v, int c) {
        if (val[node] == v) { cnt[node] += c; return; }
        if (cnt[node] >= c) cnt[node] -= c;
        else { val[node] = v; cnt[node] = c - cnt[node]; }
    }
    private void build(int[] a, int node, int lo, int hi) {
        if (lo == hi) { val[node] = a[lo]; cnt[node] = 1; return; }
        int mid = (lo + hi) / 2;
        build(a, 2*node, lo, mid);
        build(a, 2*node+1, mid+1, hi);
        val[node] = val[2*node]; cnt[node] = cnt[2*node];
        merge(node, val[2*node+1], cnt[2*node+1]);
    }
    private void qry(int node, int lo, int hi, int l, int r, int[] res) {
        if (r < lo || hi < l) return;
        if (l <= lo && hi <= r) { merge(res, val[node], cnt[node]); return; }
        int mid = (lo + hi) / 2;
        qry(2*node, lo, mid, l, r, res);
        qry(2*node+1, mid+1, hi, l, r, res);
    }
    private void merge(int[] res, int v, int c) {
        if (res[0] == v) { res[1] += c; return; }
        if (res[1] >= c) res[1] -= c;
        else { res[0] = v; res[1] = c - res[1]; }
    }
    public int query(int left, int right, int threshold) {
        int[] res = {0, 0};
        qry(1, 0, n-1, left, right, res);
        List<Integer> v = pos.get(res[0]);
        int c = upperBound(v, right) - lowerBound(v, left);
        return c >= threshold ? res[0] : -1;
    }
    private int lowerBound(List<Integer> v, int x) {
        int lo = 0, hi = v.size();
        while (lo < hi) { int m = (lo+hi)/2; if (v.get(m) < x) lo = m+1; else hi = m; }
        return lo;
    }
    private int upperBound(List<Integer> v, int x) {
        int lo = 0, hi = v.size();
        while (lo < hi) { int m = (lo+hi)/2; if (v.get(m) <= x) lo = m+1; else hi = m; }
        return lo;
    }
}

