var MajorityChecker = function(arr) {
    this.n = arr.length;
    this.pos = new Map();
    arr.forEach((v, i) => {
        if (!this.pos.has(v)) this.pos.set(v, []);
        this.pos.get(v).push(i);
    });
    this.val = new Array(4*this.n).fill(0);
    this.cnt = new Array(4*this.n).fill(0);
    const build = (node, lo, hi) => {
        if (lo === hi) { this.val[node] = arr[lo]; this.cnt[node] = 1; return; }
        const mid = (lo + hi) >> 1;
        build(2*node, lo, mid);
        build(2*node+1, mid+1, hi);
        this.val[node] = this.val[2*node]; this.cnt[node] = this.cnt[2*node];
        this.merge(node, this.val[2*node+1], this.cnt[2*node+1]);
    };
    build(1, 0, this.n - 1);
};

MajorityChecker.prototype.merge = function(node, v, c) {
    if (this.val[node] === v) { this.cnt[node] += c; return; }
    if (this.cnt[node] >= c) this.cnt[node] -= c;
    else { this.val[node] = v; this.cnt[node] = c - this.cnt[node]; }
};

MajorityChecker.prototype.query = function(left, right, threshold) {
    const qry = (node, lo, hi, l, r) => {
        if (r < lo || hi < l) return null;
        if (l <= lo && hi <= r) return [this.val[node], this.cnt[node]];
        const mid = (lo + hi) >> 1;
        const a = qry(2*node, lo, mid, l, r), b = qry(2*node+1, mid+1, hi, l, r);
        if (!a) return b;
        if (!b) return a;
        if (a[0] === b[0]) return [a[0], a[1] + b[1]];
        if (a[1] >= b[1]) return [a[0], a[1] - b[1]];
        return [b[0], b[1] - a[1]];
    };
    const res = qry(1, 0, this.n - 1, left, right);
    const v = this.pos.get(res[0]) || [];
    let lo = 0, hi = v.length;
    while (lo < hi) { const m = (lo+hi)>>1; if (v[m] < left) lo = m+1; else hi = m; }
    const start = lo; hi = v.length;
    while (lo < hi) { const m = (lo+hi)>>1; if (v[m] <= right) lo = m+1; else hi = m; }
    return (lo - start >= threshold) ? res[0] : -1;
};
